<div class="page-heading"><div><span class="eyebrow">YOUR DOCUMENT ARCHIVE</span><h1>Documents</h1><p>Receipts, invoices and supporting files.</p></div><button class="button primary" data-dialog="upload-dialog"><?= icon('upload') ?>Upload document</button></div>
<?php if($error): ?><div class="notice error" role="alert"><?= e($error) ?></div><?php endif ?>
<div class="section-heading"><h2>Recent files <span class="count"><?= count($documents) ?></span></h2><span class="muted">Latest 200 documents</span></div><div class="table-wrap"><table><thead><tr><th>File</th><th>Linked entry</th><th>Uploaded</th><th>Size</th><th>Actions</th></tr></thead><tbody><?php foreach($documents as $d): ?><tr><td><a class="row-title" href="<?= e(url('document-download',['id'=>$d['id']])) ?>"><span class="entry-symbol document"><?= icon('file-text') ?></span><span><?= e($d['original_name']) ?><small><?= e(strtoupper(pathinfo($d['stored_name'],PATHINFO_EXTENSION))) ?></small></span></a></td><td><?php if($d['entry_id']): ?><a class="text-link" href="<?= e(url('entry',['id'=>$d['entry_id']])) ?>"><?= e($d['entry_description']) ?></a><?php else: ?><span class="muted">Unlinked</span><?php endif ?></td><td class="nowrap"><?= short_date($d['created_at']) ?></td><td><?= number_format($d['size']/1024,0) ?> KB</td><td><div class="inline-form"><a class="icon-button" href="<?= e(url('document-download',['id'=>$d['id']])) ?>" title="Download" aria-label="Download <?= e($d['original_name']) ?>"><?= icon('download') ?></a><form method="post" action="<?= e(url('document-delete')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $d['id'] ?>"><button class="icon-button negative" data-confirm="Delete this document permanently?" title="Delete document" aria-label="Delete <?= e($d['original_name']) ?>"><?= icon('x') ?></button></form></div></td></tr><?php endforeach ?><?php if(!$documents): ?><tr><td colspan="5"><div class="empty-state"><?= icon('upload') ?><h3>A place for every document</h3><p>Upload your first receipt or invoice.</p><button class="button" data-dialog="upload-dialog"><?= icon('plus') ?>Add a document</button></div></td></tr><?php endif ?></tbody></table></div>
<dialog id="upload-dialog"><div class="dialog-heading"><h2>Upload document</h2><button class="icon-button" data-close-dialog aria-label="Close" title="Close"><?= icon('x') ?></button></div><form method="post" enctype="multipart/form-data" class="stack-form" action="<?= e(url('documents')) ?>"><?= csrf_field() ?><label>Document<input type="file" name="document" accept=".pdf,.jpg,.jpeg,.png,.webp" required><small>PDF, JPG, PNG or WebP. Maximum 10 MB.</small></label><label>Link to an entry<select name="entry_id"><option value="">Keep in archive</option><?php foreach($entries as $row): ?><option value="<?= $row['id'] ?>"><?= e(ucfirst($row['type']).' #'.$row['id'].' - '.$row['description']) ?></option><?php endforeach ?></select></label><button class="button primary"><?= icon('upload') ?>Upload document</button></form></dialog>
